INSERT INTO public.project_issues (id, project_id, project_name, client_id, client_name, ticket_number, title, description, issue_type, priority, status, reporter_name, reporter_email, reporter_phone, admin_notes, resolution_notes, assigned_to) VALUES
('f0000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000001', 'AI Voice Agent & Support Pipeline', '20000000-0000-0000-0000-000000000001', 'Shrawello Systems', 'ISSUE-2026-001', 'Voice stream echo during LiveKit WebRTC reconnect', 'When switching between Wi-Fi and 5G cellular, the agent audio produces a 1.2s delayed duplicate echo. Steps: start call on mobile Safari, toggle Wi-Fi off.', 'Bug', 'High', 'IN PROGRESS', 'Sarah Jenkins', 'sjenkins@apexlogistics.io', '+1 (555) 382-9012', 'Assigned to Natalia to adjust WebRTC echo cancellation constraints.', 'Implementing buffer flush on iceconnectionstatechange event.', 'Natalia Varnan'),
('f0000000-0000-0000-0000-000000000002', '30000000-0000-0000-0000-000000000001', 'AI Voice Agent & Support Pipeline', '20000000-0000-0000-0000-000000000001', 'Shrawello Systems', 'ISSUE-2026-002', 'Custom voice personality tone needs to be more formal', 'Our executive board requested that the customer support tone avoids casual greetings like "Hey there" and instead uses "Good morning/afternoon, thank you for calling Shrawello".', 'Content Change', 'Medium', 'RESOLVED', 'Sarah Jenkins', 'sjenkins@apexlogistics.io', '+1 (555) 382-9012', 'Prompt modified in ElevenLabs dynamic system instructions.', 'Updated system prompt and greeting fallback in production agent.', 'Abhinav'),
('f0000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000002', 'Development Basics & Workflow Hub', '20000000-0000-0000-0000-000000000002', 'Aether Capital', 'ISSUE-2026-003', 'SEC 10-K parsing timeout on reports exceeding 200 pages', 'When ingesting large annual filings with heavy tables, the background worker times out after 60 seconds.', 'Performance', 'Critical', 'REPORTED', 'Marcus Sterling', 'm.sterling@vanguardft.co.uk', null, 'Need to chunk PDF tables into Redis background queue.', null, 'Natalia Varnan'),
('f0000000-0000-0000-0000-000000000004', '30000000-0000-0000-0000-000000000004', 'OmniChannel WhatsApp & Voice AI Bot', '20000000-0000-0000-0000-000000000004', 'Zomira Retail Hub', 'ISSUE-2026-101', 'WhatsApp Webhook timeouts during flash sale traffic spikes', 'During our Saturday 8 PM flash sale, incoming customer inquiries were queued for over 45 seconds before the bot answered. Need to increase concurrency worker threshold.', 'Bug', 'High', 'IN PROGRESS', 'Rohan Deshmukh', 'rohan@zomiraretail.com', '+91 98201 44882', 'Scaling FastAPI webhook workers from 2 to 8 instances on AWS ECS.', 'Configured Redis queue with horizontal autoscaling for Meta webhook endpoints.', 'Natalia Varnan'),
